package com.sistemahospitalar.hospital.model; import com.sistemahospitalar.hospital.model.enums.*; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*; import java.time.*;
@Entity @Getter @Setter @NoArgsConstructor @EqualsAndHashCode(callSuper=true) public class ProcedimentoCirurgico extends Atendimento { @NotBlank @Column(nullable=false,length=200) private String descricao; @NotBlank @Column(nullable=false,length=100) private String tipoCirurgia; @Size(max=1000) private String observacoesPreOperatorias; @Size(max=1000) private String observacoesPosOperatorias; private LocalDateTime dataHoraEfetiva; @Enumerated(EnumType.STRING) @Column(nullable=false) private StatusProcedimentoEnum statusProcedimento=StatusProcedimentoEnum.AGENDADO; @Override public boolean validarCondicoes(){return getProfissionalResponsavel() instanceof Cirurgiao;} public void concluir(){if(statusProcedimento!=StatusProcedimentoEnum.EM_ANDAMENTO) throw new IllegalStateException("Procedimento só pode ser concluído após ser iniciado."); statusProcedimento=StatusProcedimentoEnum.CONCLUIDO; dataHoraEfetiva=LocalDateTime.now();} }
